import React, { useState, useEffect } from 'react';
import { Route, Routes, Link, useNavigate } from 'react-router-dom';
import ResortList from './components/ResortList'; // Adjust path if needed
import ResortDetails from './components/ResortDetails'; // Adjust path if needed
import Register from './components/Register'; // Adjust path if needed
import Login from './components/Login'; // Adjust path if needed
import { fetchResorts, fetchResort } from './api'; // Adjust path if needed
import { useAuth } from './components/AuthProvider'; // Ensure correct path to AuthProvider

function App() {
  const [resorts, setResorts] = useState([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const { isAuthenticated, login, logout } = useAuth(); // Correct hook destructuring
  const navigate = useNavigate();

  // Redirect to login if not authenticated
  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/login');
    }
  }, [isAuthenticated, navigate]);

  // Fetch resorts when authenticated
  useEffect(() => {
    const loadResorts = async () => {
      setLoading(true);
      setError(null);
      try {
        const data = await fetchResorts();
        if (Array.isArray(data)) {
          setResorts(data);
        } else {
          console.error('Unexpected data format:', data);
        }
      } catch (error) {
        setError('Error loading resorts');
        console.error('Error loading resorts:', error);
      } finally {
        setLoading(false);
      }
    };

    if (isAuthenticated) {
      loadResorts();
    }
  }, [isAuthenticated]);

  // Handle search functionality
  const handleSearch = async () => {
    setLoading(true);
    setError(null);
    try {
      const resortData = await fetchResort(search);
      if (resortData) {
        setResorts([resortData]);
      } else {
        setError('No data found for the given search term');
      }
    } catch (error) {
      setError('Error searching for resort');
      console.error('Error searching for resort:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <nav>
        <ul>
          {isAuthenticated ? (
            <>
              <li><Link to="/">Home</Link></li>
              <li><button onClick={() => { logout(); navigate('/login'); }}>Logout</button></li>
            </>
          ) : (
            <>
              <li><Link to="/register">Register</Link></li>
              <li><Link to="/login">Login</Link></li>
            </>
          )}
        </ul>
      </nav>

      <Routes>
        <Route
          path="/"
          element={
            isAuthenticated ? (
              <div>
                <input
                  type="text"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Search for resorts"
                />
                <button onClick={handleSearch}>Search</button>
                {loading && <p>Loading...</p>}
                {error && <p>{error}</p>}
                <ResortList resorts={resorts} />
              </div>
            ) : (
              <div>Please log in to view resorts.</div>
            )
          }
        />
        <Route path="/register" element={<Register />} />
        <Route path="/login" element={<Login />} />
        <Route path="/resort/:slug" element={<ResortDetails />} />
      </Routes>
    </div>
  );
}

export default App;
